311	func buildTextMatchCondition(call *exprv1.Expr_Call, schema Schema, mode TextMatchMode) (Condition, error) {
312		if call.Target == nil {
313			return nil, errors.New("text match requires a target")
314		}
315		targetName, err := getIdentName(call.Target)
316		if err != nil {
317			return nil, err
318		}
319	
320		field, ok := schema.Field(targetName)
321		if !ok {
322			return nil, errors.Errorf("unknown identifier %q", targetName)
323		}
324		if !field.SupportsContains {
325			return nil, errors.Errorf("identifier %q does not support text matching", targetName)
326		}
327		if len(call.Args) != 1 {
328			return nil, errors.New("text match expects exactly one argument")
329		}
330		value, err := getConstValue(call.Args[0])
331		if err != nil {
332			return nil, errors.Wrap(err, "text match only supports literal arguments")
333		}
334		str, ok := value.(string)
335		if !ok {
336			return nil, errors.New("text match argument must be a string")
337		}
338		return &TextMatchCondition{
339			Field: targetName,
340			Mode:  mode,
341			Value: str,
342		}, nil
343	}
