42		switch {
43		case result.unsatisfiable:
44			return Statement{
45				SQL:  "1 = 0",
46				Args: args,
47			}, nil
48		case result.trivial:
49			return Statement{
50				SQL:  "",
51				Args: args,
52			}, nil
53		default:
54			return Statement{
55				SQL:  result.sql,
56				Args: args,
57			}, nil
